#include <stdint.h>
#include <stdio.h>
#include "led.h"
#include "adc.h"
#include "registers.h"


int main(void)
{
	led_init();
	adc_init();

	uint16_t res ;

	while(1)
	{
		res = adc_read();
		if(res <= 1366)
		{
			led_on(LED1);
			led_off(LED2);
			led_off(LED3);
		}
		else if(res <= 2732)
		{
			led_on(LED2);
			led_off(LED1);
			led_off(LED3);
		}
		else
		{
			led_on(LED3);
			led_off(LED1);
			led_off(LED2);
		}
	}

}
